/* ---------------- Deep dive ---------------- */
const Pp=s=>`<p>${s}</p>`;
const DD=[
 ['elec',t2('Electrics in detail','Elektrisk i detalj'),t2('alternators, starter-generators, IDGs, TRs, inverters','alternatorer, startergeneratorer, IDG, TR, invertere'),t2(
  Pp('<b>Alternator (light aircraft):</b> engine-driven, makes AC inside and rectifies it to DC. It needs field current from the bus to start producing, so with a completely flat battery it may not come on line. A voltage regulator holds the output at about 14 or 28 V; an over-voltage relay takes it off line if the regulator fails. The <b>ammeter</b> shows charge (+) or discharge (−) of the battery; a <b>loadmeter</b> shows the alternator output.')+
  Pp('<b>Starter-generator (turboprop):</b> one machine that is a motor for the start and a DC generator afterwards. Generator control units connect it to its bus and protect against over-voltage and reverse current. Bus ties let one generator feed everything; an essential bus fed through diodes from several buses keeps the important users alive.')+
  Pp('<b>Inverter:</b> turns DC into AC (typically 115 V and 26 V, 400 Hz) for AC instruments and avionics. <b>TR (transformer-rectifier):</b> the opposite, AC into 28 V DC, used on jets.')+
  Pp('<b>IDG (jet):</b> the engine speed varies, but AC must be at a constant 400 Hz, so a constant speed drive inside the IDG turns the generator at a fixed speed. It has its own oil; if it overheats or loses oil it is <b>disconnected</b> by the crew and cannot be reconnected in flight. AC generators are never paralleled on most twin jets: the bus tie only closes to let one source feed a side that has lost its own (no-break power transfer is a ground feature on some types).')+
  Pp('<b>Batteries</b> start the APU and are the last source. Certification asks for a minimum time on battery (typically 30 minutes); the essential buses are chosen so that one set of instruments, one radio and the essentials remain.'),
  Pp('<b>Alternator (småfly):</b> motordrevet, lager AC inni og likeretter den til DC. Den trenger feltstrøm fra skinnen for å begynne å produsere, så med et helt flatt batteri kommer den kanskje ikke inn. En spenningsregulator holder utgangen på rundt 14 eller 28 V; et overspenningsrelé kobler den ut hvis regulatoren svikter. <b>Amperemeteret</b> viser lading (+) eller utlading (−) av batteriet; en <b>lastmåler</b> viser alternatorens ytelse.')+
  Pp('<b>Startergenerator (turboprop):</b> én maskin som er motor under start og DC-generator etterpå. Generatorkontrollenheter kobler den til skinnen og beskytter mot overspenning og tilbakestrøm. Skinnebrytere lar én generator mate alt; en essensiell skinne matet gjennom dioder fra flere skinner holder de viktige brukerne i live.')+
  Pp('<b>Inverter:</b> gjør DC om til AC (typisk 115 V og 26 V, 400 Hz) for AC-instrumenter og avionikk. <b>TR (transformator-likeretter):</b> det motsatte, AC til 28 V DC, brukt på jetfly.')+
  Pp('<b>IDG (jet):</b> motorturtallet varierer, men AC må ha konstant 400 Hz, så en konstantfartsdrift i IDG-en driver generatoren med fast turtall. Den har egen olje; blir den for varm eller mister olje, <b>kobles den fra</b> av besetningen og kan ikke kobles til igjen i lufta. AC-generatorer kobles aldri i parallell på de fleste tomotors jetfly: skinnebryteren lukker bare for å la én kilde mate en side som har mistet sin egen.')+
  Pp('<b>Batteriene</b> starter APU-en og er siste kilde. Sertifiseringen krever en minstetid på batteri (typisk 30 minutter); de essensielle skinnene er valgt slik at ett sett instrumenter, én radio og det essensielle er igjen.'))],
 ['hyd',t2('Hydraulics in detail','Hydraulikk i detalj'),t2('pressure, pumps, accumulators, the PTU and the RAT','trykk, pumper, akkumulatorer, PTU og RAT'),t2(
  Pp('A hydraulic system turns a small, light pump into large forces: pressure × piston area. Most transport aircraft run at about <b>3000 psi</b> (some newer ones at 5000 psi to save weight). Fluid is a fire-resistant phosphate-ester type in most transport aircraft and a mineral oil (red) in many light aircraft; the two must never be mixed.')+
  Pp('<b>Pumps:</b> engine-driven pumps (EDPs) are variable-displacement and give the main flow; electric pumps (AC motor) back them up and pressurise the system on the ground. A <b>reservoir</b> is pressurised (by bleed air or the system itself) to stop the pump inlet cavitating at altitude. <b>Accumulators</b> (a gas pre-charge, typically nitrogen, behind a piston or bladder) store pressure, damp pressure surges and keep the brakes working for a few applications without pumps. <b>Priority valves</b> cut off heavy, less important users when the pressure is low, so the flight controls get it first. <b>Fuses</b> close a line that suddenly flows too much (a burst pipe).')+
  Pp('<b>PTU:</b> a hydraulic motor in one system driving a pump in another, back to back. It runs automatically when the pressure difference exceeds a threshold (about 500 psi, typical), barks on the ground, and is inhibited when one side has lost its fluid. <b>RAT:</b> a small propeller that drops into the airflow after a total loss of engines or AC, driving a hydraulic pump (and through it, or directly, a generator). It needs airspeed and is stowed only on the ground.'),
  Pp('Et hydraulikksystem gjør en liten, lett pumpe om til store krefter: trykk × stempelareal. De fleste trafikkfly bruker rundt <b>3000 psi</b> (noen nyere 5000 psi for å spare vekt). Væsken er en brannhemmende fosfatestertype i de fleste trafikkfly og en mineralolje (rød) i mange småfly; de to må aldri blandes.')+
  Pp('<b>Pumper:</b> motordrevne pumper (EDP) har variabel slagvolum og gir hovedstrømmen; elektriske pumper (AC-motor) er reserve og gir trykk på bakken. Et <b>reservoar</b> er trykksatt (med bleed-luft eller av systemet selv) så pumpeinnløpet ikke kaviterer i høyden. <b>Akkumulatorer</b> (en gassforladning, typisk nitrogen, bak et stempel eller en blære) lagrer trykk, demper trykkstøt og holder bremsene i gang noen bremsinger uten pumper. <b>Prioritetsventiler</b> kutter tunge, mindre viktige brukere når trykket er lavt, så flykontrollene får det først. <b>Sikringer</b> stenger en ledning som plutselig får for stor strøm (et sprukket rør).')+
  Pp('<b>PTU:</b> en hydraulisk motor i ett system som driver en pumpe i et annet, rygg mot rygg. Den går automatisk når trykkforskjellen er over en grense (rundt 500 psi, typisk), bjeffer på bakken, og sperres når den ene siden har mistet væsken. <b>RAT:</b> en liten propell som faller ut i luftstrømmen etter totalt tap av motorer eller AC, og driver en hydraulikkpumpe (og gjennom den, eller direkte, en generator). Den trenger fart og felles inn bare på bakken.'))],
 ['fuel',t2('Fuel in detail','Drivstoff i detalj'),t2('fuels, feeding, wing bending relief, cold fuel, jettison','drivstofftyper, mating, vingeavlastning, kaldt drivstoff, dumping'),t2(
  Pp('<b>Fuels:</b> piston engines burn AVGAS (100LL is blue); turbine engines burn kerosene, Jet A-1 in Europe, with a freezing point of −47 °C or lower. Jet A-1 in a piston engine causes detonation; AVGAS in a turbine is allowed only in limited amounts by some manufacturers. Water collects at the low points: sample the drains before flight.')+
  Pp('<b>Feeding:</b> boost pumps push fuel to the engine so the engine-driven pump never sucks against altitude (vapour lock). With boost pumps lost, many jets can still <b>suction feed</b> (gravity feed) from the wing tanks, but only up to a limited altitude. Light twins use the electric aux pump for take-off and landing, and when the engine-driven pump fails.')+
  Pp('<b>Centre tank first, wings last:</b> fuel in the wings hangs below the lift and reduces the bending at the wing root, so jets burn the centre tank first and the outer wing cells last. It is the same idea as the maximum zero fuel mass.')+
  Pp('<b>Cold fuel:</b> on long flights at high altitude the fuel cools towards the outside air temperature. A low fuel temperature is a reason to descend or fly faster (warmer ram air). Fuel heaters (often using engine oil) stop ice crystals blocking the filters.')+
  Pp('<b>Jettison:</b> fitted where the maximum take-off mass is much higher than the maximum landing mass (large jets). It dumps fuel overboard through outlets near the wing tips, down to a set minimum, to land sooner after an emergency. Twins of medium size usually have no jettison and land overweight if they must.'),
  Pp('<b>Drivstoff:</b> stempelmotorer bruker AVGAS (100LL er blått); turbinmotorer bruker parafin, Jet A-1 i Europa, med frysepunkt −47 °C eller lavere. Jet A-1 i en stempelmotor gir detonasjon; AVGAS i en turbin tillates bare i begrensede mengder av noen produsenter. Vann samler seg på de laveste punktene: ta prøve fra dreneringene før flyging.')+
  Pp('<b>Mating:</b> boostpumper skyver drivstoffet til motoren så den motordrevne pumpen aldri suger mot høyden (damplås). Uten boostpumper kan mange jetfly fortsatt <b>sugemate</b> (gravitasjonsmate) fra vingetankene, men bare opp til en begrenset høyde. Lette tomotors bruker den elektriske ekstrapumpen ved avgang og landing, og når den motordrevne pumpen svikter.')+
  Pp('<b>Sentertanken først, vingene sist:</b> drivstoff i vingene henger under løftet og reduserer bøyningen ved vingeroten, så jetfly bruker sentertanken først og de ytre vingecellene sist. Det er samme idé som maksimal nullbrenselmasse.')+
  Pp('<b>Kaldt drivstoff:</b> på lange flyginger høyt oppe kjøles drivstoffet mot utetemperaturen. Lav drivstofftemperatur er en grunn til å gå ned eller fly fortere (varmere stuvingsluft). Drivstoffvarmere (ofte med motorolje) hindrer at iskrystaller tetter filtrene.')+
  Pp('<b>Dumping:</b> finnes der maksimal startmasse er mye høyere enn maksimal landingsmasse (store jetfly). Den dumper drivstoff over bord gjennom utløp nær vingespissene, ned til et fast minimum, for å lande raskere etter en nødsituasjon. Mellomstore tomotors har som regel ikke dumping og lander overvektige om nødvendig.'))],
 ['fc',t2('Flight controls in detail','Flykontroller i detalj'),t2('tabs, boost, fly-by-wire laws and protections','ror, assistanse, fly-by-wire-lover og beskyttelser'),t2(
  Pp('<b>Tabs</b> are small hinged surfaces on the trailing edge of a control surface. A <b>trim tab</b> is set by the pilot to hold the surface where it is wanted with no force. A <b>balance tab</b> moves opposite to the surface automatically and reduces the force. A <b>servo tab</b> is moved by the pilot instead of the surface: the air on the tab moves the surface. A <b>spring tab</b> only starts to help when the forces are high (at high speed). An <b>anti-balance tab</b> moves the same way as the surface and makes it heavier (often on stabilators).')+
  Pp('<b>Powered controls:</b> above a certain size and speed the forces are too large for tabs: hydraulic actuators move the surfaces, and artificial feel gives the pilot a force that grows with speed. The surfaces are then <b>irreversible</b>: air loads do not move the stick.')+
  Pp('<b>Fly-by-wire:</b> the stick or yoke sends an electrical demand to several flight control computers, which drive the actuators. In <b>normal law</b> they protect bank angle, load factor (typically +2.5 g / −1 g clean, +2 g / 0 g with flaps), pitch attitude, high angle of attack and overspeed; you can pull full back in an escape manoeuvre and get the most the aircraft can safely give. When sensors or computers fail, the laws degrade: <b>alternate law</b> keeps some help but loses most protections; <b>direct law</b> gives a plain stick-to-surface relation with no automatic trim; a <b>mechanical backup</b> (stabiliser trim and rudder on many types) keeps control while systems are restored. The names differ by manufacturer, the idea is the same.'),
  Pp('<b>Ror</b> er små hengslede flater på bakkanten av en rorflate. Et <b>trimror</b> stilles av piloten for å holde flaten der den skal være uten kraft. Et <b>balanseror</b> går automatisk motsatt vei av flaten og reduserer kraften. Et <b>servoror</b> beveges av piloten i stedet for flaten: luften på roret beveger flaten. Et <b>fjærror</b> begynner først å hjelpe når kreftene er store (i høy fart). Et <b>antibalanseror</b> går samme vei som flaten og gjør den tyngre (ofte på helhaler).')+
  Pp('<b>Kraftstyring:</b> over en viss størrelse og fart blir kreftene for store for ror: hydrauliske aktuatorer beveger flatene, og kunstig følelse gir piloten en kraft som øker med farten. Flatene er da <b>irreversible</b>: luftkrefter beveger ikke stikka.')+
  Pp('<b>Fly-by-wire:</b> stikka eller rattet sender et elektrisk ønske til flere flykontrolldatamaskiner, som driver aktuatorene. I <b>normal lov</b> beskytter de krengning, lastfaktor (typisk +2,5 g / −1 g rent, +2 g / 0 g med flaps), stampvinkel, høy angrepsvinkel og overfart; du kan trekke helt bak i en unnamanøver og få det mest flyet trygt kan gi. Når sensorer eller datamaskiner svikter, degraderes lovene: <b>alternativ lov</b> beholder noe hjelp, men mister de fleste beskyttelsene; <b>direkte lov</b> gir en ren sammenheng mellom stikke og rorflate uten automatisk trim; en <b>mekanisk reserve</b> (stabilisatortrim og sideror på mange typer) holder kontrollen mens systemene kommer tilbake. Navnene varierer mellom produsenter, ideen er den samme.'))],
 ['gear',t2('Gear and brakes in detail','Understell og bremser i detalj'),t2('locks, warnings, anti-skid, autobrake, hydroplaning, brake heat','låser, varsler, antiskrens, autobrems, vannplaning, bremsevarme'),t2(
  Pp('<b>Locks and lights:</b> each leg has an uplock and a downlock; a green light means down and locked, red means in transit or not agreeing with the lever. A <b>squat switch</b> (weight-on-wheels) prevents retraction on the ground and tells many systems that the aircraft is on the ground. A <b>warning horn</b> sounds with the gear up and the power reduced or landing flap set.')+
  Pp('<b>Emergency extension:</b> light aircraft use free fall or a hand crank or hand pump; turboprops and jets release the uplocks mechanically and let the gear fall by gravity, helped by the airflow and springs. On most types it cannot be retracted afterwards.')+
  Pp('<b>Anti-skid</b> compares each wheel’s speed with the aircraft’s and releases pressure on a wheel that starts to lock, keeping the tyre near the slip that gives most friction, with cornering force left for steering. <b>Autobrake</b> commands a deceleration, not a pressure: low and medium for landing, maximum armed for a rejected take-off. Without anti-skid, brake pressure must be limited by the pilot.')+
  Pp('<b>Hydroplaning:</b> on standing water deeper than the tread can drain (about 3 mm or more), a water wedge lifts the tyre. Rule of thumb: a rotating tyre hydroplanes from about <b>9 × √p</b> kt (p = tyre pressure in psi), a tyre not yet spun up at touchdown from about <b>7.7 × √p</b> kt. Never land with the brakes on.')+
  Pp('<b>Brake heat:</b> braking turns the kinetic energy into heat. Hot brakes after a short turnaround or a high-energy stop can delay the next departure, because a rejected take-off needs cool brakes; fusible plugs in the wheels let the tyre deflate before it bursts.'),
  Pp('<b>Låser og lys:</b> hvert bein har en opplås og en nedlås; grønt lys betyr nede og låst, rødt betyr i bevegelse eller uenig med spaken. En <b>squat switch</b> (vekt på hjul) hindrer innfelling på bakken og forteller mange systemer at flyet står på bakken. Et <b>varselhorn</b> lyder med understellet oppe og kraften redusert eller landingsflaps satt.')+
  Pp('<b>Nødutfelling:</b> småfly bruker fritt fall eller en håndsveiv eller håndpumpe; turboproper og jetfly utløser opplåsene mekanisk og lar understellet falle med tyngdekraften, hjulpet av luftstrøm og fjærer. På de fleste typer kan det ikke felles inn igjen etterpå.')+
  Pp('<b>Antiskrens</b> sammenligner hvert hjuls fart med flyets og slipper trykket på et hjul som begynner å låse, så dekket holdes nær den sluringen som gir mest friksjon, med sidekraft igjen til styring. <b>Autobrems</b> styrer en retardasjon, ikke et trykk: lav og middels for landing, maks armert for avbrutt start. Uten antiskrens må piloten begrense bremsetrykket.')+
  Pp('<b>Vannplaning:</b> på stående vann dypere enn mønsteret klarer å drenere (rundt 3 mm eller mer), løfter en vannkile dekket. Tommelfingerregel: et roterende dekk vannplaner fra rundt <b>9 × √p</b> kt (p = dekktrykk i psi), et dekk som ikke har spunnet opp ved setting fra rundt <b>7,7 × √p</b> kt. Land aldri med bremsene på.')+
  Pp('<b>Bremsevarme:</b> bremsing gjør bevegelsesenergien om til varme. Varme bremser etter kort bakketid eller et hardt stopp kan forsinke neste avgang, fordi en avbrutt start trenger kalde bremser; smeltepropper i hjulene slipper luften ut av dekket før det sprekker.'))],
 ['bleed',t2('Bleed air, anti-ice and fire protection','Bleed-luft, avising og brannvern'),t2('the other systems around the engines','de andre systemene rundt motorene'),t2(
  Pp('<b>Bleed air</b> is hot, compressed air taken from the compressor of a turbine engine. It is cooled in a precooler and feeds the air conditioning packs, the wing and engine anti-ice and on many types the hydraulic reservoirs. Each engine normally supplies its own side; a <b>crossbleed</b> valve lets one side feed the other, and the APU can supply the packs on the ground. A bleed leak (hot air in the wing or pylon) is isolated by closing the bleed on that side and keeping the crossbleed shut. Turboprops often use bleed air for de-icing boots; many light piston aircraft have none and use vacuum or electric de-ice where fitted. Pressurisation is in its own lab.')+
  Pp('<b>Fire protection:</b> engines and the APU have detection loops; on transport aircraft two loops in AND logic, so a single faulty loop gives no false warning, while a failed loop is deselected so the other can still warn. The fire handle or pushbutton closes the fuel (LP or firewall valve), hydraulic, bleed and generator connections to that engine and arms the extinguisher bottles. Jets typically carry two bottles per engine and one for the APU; light twins often have no engine extinguisher at all.'),
  Pp('<b>Bleed-luft</b> er varm, komprimert luft tatt fra kompressoren i en turbinmotor. Den kjøles i en forkjøler og mater klimaanleggets pakker, vinge- og motoravisingen og på mange typer hydraulikkreservoarene. Hver motor forsyner normalt sin egen side; en <b>crossbleed</b>-ventil lar én side forsyne den andre, og APU-en kan forsyne pakkene på bakken. En bleed-lekkasje (varm luft i vingen eller pylonen) isoleres ved å stenge bleed på den siden og holde crossbleed stengt. Turboproper bruker ofte bleed-luft til avisingsmatter; mange lette stempelfly har ingen og bruker vakuum eller elektrisk avising der det finnes. Trykkabinen har sin egen lab.')+
  Pp('<b>Brannvern:</b> motorer og APU har deteksjonssløyfer; på trafikkfly to sløyfer i OG-logikk, så én defekt sløyfe ikke gir falsk varsel, mens en sviktende sløyfe velges bort så den andre fortsatt kan varsle. Brannhåndtaket eller -knappen stenger drivstoff (LP- eller brannskottventil), hydraulikk, bleed og generatorforbindelse til motoren og armerer slokkeflaskene. Jetfly har typisk to flasker per motor og én for APU; lette tomotors har ofte ingen motorslokking i det hele tatt.'))]];
function drawDD(){ const open=[...document.querySelectorAll('#ddList details[open]')].map(d=>d.id);
  el('ddList').innerHTML=DD.map(([id,t,s,b])=>`<details class="dfold" id="dd-${id}"><summary>${L(t)} <small>${L(s)}</small></summary><div>${L(b)}</div></details>`).join('');
  open.forEach(i=>{ const d=el(i); if(d) d.open=true; }); }

/* ---------------- Test yourself ---------------- */
function drawTake(){ const TK=[
  t2('<b>Every system is sources → bus or system → users.</b> A failure takes away a source; what still works is whatever has another path.','<b>Hvert system er kilder → skinne eller system → brukere.</b> En feil tar bort en kilde; det som fortsatt virker, er det som har en annen vei.'),
  t2('<b>Electrics grow with the aircraft:</b> 14/28 V DC alternators (piston), 28 V DC starter-generators with inverters (turboprop), 115 V 400 Hz AC with IDGs, TRs, APU and RAT (jet).','<b>Elektrisk vokser med flyet:</b> 14/28 V DC alternatorer (stempel), 28 V DC startergeneratorer med invertere (turboprop), 115 V 400 Hz AC med IDG, TR, APU og RAT (jet).'),
  t2('<b>A piston engine needs no electrics:</b> magnetos fire it and the controls are cables. Losing the alternators costs radios, gear motor and flaps when the battery runs out.','<b>En stempelmotor trenger ikke strøm:</b> magnetene tenner den og kontrollene er kabler. Tap av alternatorene koster radio, understellsmotor og flaps når batteriet er tomt.'),
  t2('<b>Jet AC generators are never paralleled.</b> The bus tie closes only to let one source feed a side that lost its own; the APU gives back a second source.','<b>AC-generatorer på jetfly kobles aldri i parallell.</b> Skinnebryteren lukker bare for å la én kilde mate en side som har mistet sin egen; APU-en gir en ny kilde.'),
  t2('<b>Hydraulics:</b> none or a power pack (piston), one system with two engine pumps (turboprop), three independent systems (jet). The <b>PTU moves power, not fluid</b>: it cannot help after a leak.','<b>Hydraulikk:</b> ingen eller en kraftpakke (stempel), ett system med to motorpumper (turboprop), tre uavhengige systemer (jet). <b>PTU-en flytter kraft, ikke væske</b>: den kan ikke hjelpe etter en lekkasje.'),
  t2('<b>Fuel:</b> each engine from its own side; crossfeed to balance or after a pump loss, <b>never before a leak is ruled out</b>. Jets burn the centre tank first to relieve the wing root.','<b>Drivstoff:</b> hver motor fra sin egen side; kryssmating for balanse eller etter pumpetap, <b>aldri før en lekkasje er utelukket</b>. Jetfly bruker sentertanken først for å avlaste vingeroten.'),
  t2('<b>Flight controls:</b> cables and trim tabs, then servo and spring tabs, then fly-by-wire. Fly-by-wire degrades from normal to alternate to direct law, with a mechanical backup.','<b>Flykontroller:</b> kabler og trimror, så servo- og fjærror, så fly-by-wire. Fly-by-wire degraderes fra normal til alternativ til direkte lov, med en mekanisk reserve.'),
  t2('<b>Gear:</b> the backup is always gravity (free fall, crank or hand pump); three greens = down and locked. <b>Brakes:</b> anti-skid lets you use full pedal; without it, brake gently; the accumulator gives a few applications.','<b>Understell:</b> reserven er alltid tyngdekraften (fritt fall, sveiv eller håndpumpe); tre grønne = nede og låst. <b>Bremser:</b> antiskrens lar deg bruke full pedal; uten den bremser du forsiktig; akkumulatoren gir noen få bremsinger.')];
  el('take').innerHTML=TK.map(x=>`<li>${L(x)}</li>`).join(''); }

LAB.quiz(el('qbox'),'jets',()=>LAB.shuffle([
 {q:t2('What is the main electrical system of a typical jet transport?','Hva er hovedsystemet for strøm på et typisk jettrafikkfly?'),a:[t2('115 V AC at 400 Hz','115 V AC på 400 Hz'),t2('28 V DC','28 V DC'),t2('14 V DC','14 V DC')],c:0,e:t2('AC at high voltage carries large loads with light wiring; TRs make the 28 V DC.','AC med høy spenning fører store laster med lette ledninger; TR-er lager 28 V DC.')},
 {q:t2('In a turboprop with a 28 V DC system, what supplies the AC for some instruments?','I en turboprop med 28 V DC-system, hva gir AC til noen instrumenter?'),a:[t2('Inverters','Invertere'),t2('Transformer-rectifiers','Transformator-likerettere'),t2('The starter-generators directly','Startergeneratorene direkte')],c:0,e:t2('An inverter makes AC from DC. A TR does the opposite.','En inverter lager AC fra DC. En TR gjør det motsatte.')},
 {q:t2('A light piston twin loses all electrical power. The engines…','Et lett stempeltomotors mister all strøm. Motorene …'),a:[t2('keep running on their magnetos','går videre på magnetene'),t2('stop at once','stopper med en gang'),t2('run until the fuel pumps stop','går til drivstoffpumpene stopper')],c:0,e:t2('Magnetos are engine-driven and independent of the aircraft electrics; the engine-driven fuel pumps keep feeding.','Magnetene er motordrevne og uavhengige av flyets strøm; de motordrevne drivstoffpumpene fortsetter å mate.')},
 {q:t2('On a twin jet, why does the bus tie stay open when both generators work?','Hvorfor står skinnebryteren åpen på et tomotors jetfly når begge generatorene virker?'),a:[t2('AC generators are not run in parallel; each feeds its own side','AC-generatorer kjøres ikke i parallell; hver mater sin egen side'),t2('To save fuel','For å spare drivstoff'),t2('Because the batteries need it open to charge','Fordi batteriene trenger den åpen for å lades')],c:0,e:t2('Keeping the sides apart means one fault cannot take down both; the tie closes only to let one source feed a side that has lost its own.','Når sidene holdes adskilt, kan ikke én feil ta ned begge; bryteren lukker bare for å la én kilde mate en side som har mistet sin egen.')},
 {q:t2('What does a hydraulic PTU do?','Hva gjør en hydraulisk PTU?'),a:[t2('It transfers power from one system to another without mixing fluid','Den overfører kraft fra ett system til et annet uten å blande væske'),t2('It pumps fluid from a full system into an empty one','Den pumper væske fra et fullt system til et tomt'),t2('It is an emergency electrical generator','Den er en nødgenerator for strøm')],c:0,e:t2('A hydraulic motor on one side drives a pump on the other. After a leak it cannot help.','En hydraulisk motor på den ene siden driver en pumpe på den andre. Etter en lekkasje kan den ikke hjelpe.')},
 {q:t2('After both engines of a jet flame out, the RAT provides…','Etter at begge motorene på et jetfly har stanset, gir RAT-en …'),a:[t2('hydraulic pressure for one system and, through it, emergency electrics','hydraulisk trykk til ett system og, gjennom det, nødstrøm'),t2('thrust to extend the glide','skyvekraft som forlenger glidet'),t2('bleed air for pressurisation','bleed-luft til trykkabinen')],c:0,e:t2('The ram air turbine needs airspeed; it is the last hydraulic and electrical source.','Ram air-turbinen trenger fart; den er siste hydrauliske og elektriske kilde.')},
 {q:t2('In a typical turboprop twin with one hydraulic system, losing the system means…','I en typisk turboprop-tomotors med ett hydraulikksystem betyr tap av systemet …'),a:[t2('gear by free fall, no flaps or nosewheel steering, brakes from the accumulator','understell ved fritt fall, ingen flaps eller nesehjulsstyring, bremser fra akkumulatoren'),t2('no aileron or elevator control','ingen balanseror- eller høyderorskontroll'),t2('nothing, because the flight controls take over','ingenting, fordi flykontrollene tar over')],c:0,e:t2('The primary controls are on cables, so you can still fly; the hydraulic users need their backups.','De primære kontrollene går på kabler, så du kan fortsatt fly; de hydrauliske brukerne trenger sine reserver.')},
 {q:t2('Fuel on board plus fuel used is less than the fuel at take-off and one wing is light. You should first…','Drivstoff om bord pluss forbrukt er mindre enn ved avgang, og den ene vingen er lett. Du bør først …'),a:[t2('suspect a leak and locate it before using the crossfeed','mistenke lekkasje og finne den før du bruker kryssmatingen'),t2('open the crossfeed to balance','åpne kryssmatingen for å balansere'),t2('switch off all fuel pumps','slå av alle drivstoffpumper')],c:0,e:t2('Crossfeeding into a leak drains the good side too.','Kryssmating inn i en lekkasje tømmer den gode siden også.')},
 {q:t2('Why do jets use the centre tank before the wing tanks?','Hvorfor bruker jetfly sentertanken før vingetankene?'),a:[t2('Fuel in the wings relieves the bending at the wing root','Drivstoff i vingene avlaster bøyningen ved vingeroten'),t2('The centre tank fuel is warmer','Drivstoffet i sentertanken er varmere'),t2('The wing pumps are weaker','Vingepumpene er svakere')],c:0,e:t2('Same idea as the maximum zero fuel mass: weight in the wings counters the lift bending them up.','Samme idé som maksimal nullbrenselmasse: vekt i vingene motvirker løftet som bøyer dem opp.')},
 {q:t2('In a light piston twin, when is the crossfeed normally used?','Når brukes kryssmatingen normalt i et lett stempeltomotors?'),a:[t2('In single-engine flight, for range and balance','På én motor, for rekkevidde og balanse'),t2('For every take-off','Ved hver avgang'),t2('To feed both engines from one tank in normal cruise','For å mate begge motorene fra én tank i normal marsj')],c:0,e:t2('It lets the working engine use fuel from the other wing; it is not used for take-off or landing.','Den lar den virkende motoren bruke drivstoff fra den andre vingen; den brukes ikke ved avgang eller landing.')},
 {q:t2('What does a servo tab do?','Hva gjør et servoror?'),a:[t2('The pilot moves the tab; the airflow on it moves the surface','Piloten beveger roret; luftstrømmen på det beveger flaten'),t2('It makes the control heavier','Det gjør styringen tyngre'),t2('It only trims out steady forces','Det trimmer bare bort jevne krefter')],c:0,e:t2('The tab deflects opposite to the wanted surface movement, and the air does the work.','Roret slår ut motsatt vei av ønsket flatebevegelse, og luften gjør jobben.')},
 {q:t2('A fly-by-wire aircraft in alternate law has…','Et fly-by-wire-fly i alternativ lov har …'),a:[t2('reduced protections; stall and overspeed warnings remain','reduserte beskyttelser; stall- og overfartsvarsler er igjen'),t2('all protections','alle beskyttelser'),t2('no electrical signalling at all','ingen elektrisk signalering i det hele tatt')],c:0,e:t2('Most hard protections are lost when data or systems degrade; in direct law there is no help at all.','De fleste harde beskyttelsene forsvinner når data eller systemer degraderes; i direkte lov er det ingen hjelp.')},
 {q:t2('How does an emergency gear extension normally work on a turboprop or jet?','Hvordan virker nødutfelling av understellet normalt på en turboprop eller et jetfly?'),a:[t2('The uplocks are released and the gear falls by gravity, helped by the airflow','Opplåsene utløses og understellet faller med tyngdekraften, hjulpet av luftstrømmen'),t2('A second electric motor drives it down','En ekstra elektrisk motor driver det ned'),t2('The PTU lowers it','PTU-en feller det ut')],c:0,e:t2('Gravity needs no power; most types cannot retract it again afterwards.','Tyngdekraften trenger ingen kraft; de fleste typer kan ikke felle det inn igjen etterpå.')},
 {q:t2('With the anti-skid inoperative you should…','Med antiskrens ute av drift bør du …'),a:[t2('brake gently and progressively to avoid locking the wheels','bremse forsiktig og gradvis for å unngå at hjulene låser'),t2('use maximum autobrake','bruke maks autobrems'),t2('pump the brakes rapidly','pumpe bremsene raskt')],c:0,e:t2('A locked wheel loses friction and cornering force and can burst the tyre.','Et låst hjul mister friksjon og sidekraft og kan sprenge dekket.')},
 {q:t2('A rotating tyre at 200 psi hydroplanes from about…','Et roterende dekk på 200 psi vannplaner fra rundt …'),a:[t2('127 kt','127 kt'),t2('109 kt','109 kt'),t2('200 kt','200 kt')],c:0,e:t2('9 × √200 ≈ 127 kt. A non-rotating tyre at touchdown: 7.7 × √200 ≈ 109 kt.','9 × √200 ≈ 127 kt. Et dekk som ikke roterer ved setting: 7,7 × √200 ≈ 109 kt.')}]),10);

